"""256x3 uint8 colormap LUTs (generated from matplotlib). Decode: zlib+base64."""
import base64, zlib, numpy as np
_D = {
  "inferno": "",
  "magma": "",
  "plasma": "",
  "viridis": "",
  "jet": "",
  "turbo": "",
  "hot": "",
}

def lut(name):
    d = _D.get(name) or _D["inferno"]
    return np.frombuffer(zlib.decompress(base64.b64decode(d)), dtype=np.uint8).reshape(256, 3)
